        recentLocalRepositories,
        removeRecentLocalProject,
        repositories,
        releaseBranchCandidates,
        releaseSelectAllDefault,
        setReleaseSelectAllDefault,
        setSwitchBranch,
        states,
        switchBranch,
        switchProjectBranch,
    }
}

